/**
 * @file Version.hpp
 * @brief Semantic version query interface for the GridLock MPI Debugger.
 *
 * Exposes compile-time semantic version components (major, minor, patch)
 * generated by Meson into VersionConfig.hpp for display in the CLI parser,
 * About dialog, and QApplication metadata.
 */

#pragma once

#include <QString>

namespace gridlock::core {

/**
 * @brief Static utility class providing access to the application's semantic version.
 */
class Version {
public:
    /** @brief Returns the full "MAJOR.MINOR.PATCH" semantic version string. */
    static QString getString();

    /** @brief Extracts and returns the major version integer component. */
    static int getMajor();

    /** @brief Extracts and returns the minor version integer component. */
    static int getMinor();

    /** @brief Extracts and returns the patch version integer component. */
    static int getPatch();
};

} // namespace gridlock::core
